"use strict";
/**
 * Converts generate-profile.js's cookies.json (Playwright's export format)
 * into the Netscape cookies.txt format ArchiveBox's COOKIES_FILE expects.
 */
const fs = require("fs");
const cookies = JSON.parse(fs.readFileSync("/output/cookies.json", "utf8"));
const lines = [
  "# Netscape HTTP Cookie File",
  "# Generated by a scripted real-browser visit to the sites this project archives (see README.md).",
];
for (const c of cookies) {
  const domain = c.domain || "";
  const includeSubdomains = domain.startsWith(".") ? "TRUE" : "FALSE";
  const p = c.path || "/";
  const secure = c.secure ? "TRUE" : "FALSE";
  const expiry = c.expires && c.expires > 0 ? Math.floor(c.expires) : 0;
  lines.push([domain, includeSubdomains, p, secure, expiry, c.name, c.value].join("\t"));
}
fs.writeFileSync("/output/cookies.txt", lines.join("\n") + "\n");
console.log(`wrote ${cookies.length} cookies from ${new Set(cookies.map((c) => c.domain)).size} domains`);
